CREATE DATABASE customer_behavior;
Show DATABASES;
use customer_behavior;
 SELECT * from customer;
 DESCRIBE customer;
 
 SELECT COUNT(*) AS total_records
FROM customer;

-- 1. Revenue Analysis — Compared total revenue generated by male and female customers.
SELECT
    gender,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY gender;

-- 2. Discount & Spending Analysis — Identified discount users whose purchase amounts were at or above the overall average.
SELECT
    customer_id,
    purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
AND purchase_amount >= (
    SELECT AVG(purchase_amount)
    FROM customer
);

-- 3. Product Rating Analysis — Ranked the top 5 products by average review rating.
SELECT
    item_purchased,
    ROUND(AVG(review_rating), 2) AS average_product_rating
FROM customer
GROUP BY item_purchased
ORDER BY average_product_rating DESC
LIMIT 5;

-- 4. Shipping Analysis — Compared average purchase amounts for Standard and Express shipping.
SELECT
    shipping_type,
    ROUND(AVG(purchase_amount), 2) AS average_purchase
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;

-- 5. Subscription Analysis — Compared customer counts, average spending, and total revenue between subscribers and non-subscribers.
SELECT
    subscription_status,
    COUNT(customer_id) AS total_customers,
    ROUND(AVG(purchase_amount), 2) AS average_spending,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC;


-- 6. Discount Dependency Analysis — Identified the top 5 products by percentage of purchases with discounts applied.
SELECT
    item_purchased,
    ROUND(
        100.0 * SUM(
            CASE
                WHEN discount_applied = 'Yes' THEN 1
                ELSE 0
            END
        ) / COUNT(*), 2
    ) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;


-- 7. Customer Segmentation — Classified customers into New, Returning, and Loyal segments based on previous purchases.
WITH customer_type AS (
    SELECT
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases <= 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer
)
SELECT
    customer_segment,
    COUNT(*) AS number_of_customers
FROM customer_type
GROUP BY customer_segment
ORDER BY number_of_customers DESC;

-- 8. Product Popularity Analysis — Identified the top 3 most purchased products within each category.

WITH item_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(*) AS total_orders
    FROM customer
    GROUP BY category, item_purchased
),
ranked_items AS (
    SELECT
        category,
        item_purchased,
        total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY total_orders DESC, item_purchased ASC
        ) AS item_rank
    FROM item_counts
)
SELECT
    category,
    item_purchased,
    total_orders,
    item_rank
FROM ranked_items
WHERE item_rank <= 3
ORDER BY category, item_rank;

-- 9. Repeat Buyer Analysis — Compared subscription status among customers with more than 5 previous purchases.
SELECT
    subscription_status,
    COUNT(customer_id) AS repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;


-- 10. Age Group Revenue Analysis — Compared total revenue across customer age groups.

SELECT
    CASE
        WHEN age BETWEEN 18 AND 25 THEN '18-25'
        WHEN age BETWEEN 26 AND 35 THEN '26-35'
        WHEN age BETWEEN 36 AND 45 THEN '36-45'
        WHEN age BETWEEN 46 AND 55 THEN '46-55'
        WHEN age >= 56 THEN '56+'
        ELSE 'Other'
    END AS age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY
    CASE
        WHEN age BETWEEN 18 AND 25 THEN '18-25'
        WHEN age BETWEEN 26 AND 35 THEN '26-35'
        WHEN age BETWEEN 36 AND 45 THEN '36-45'
        WHEN age BETWEEN 46 AND 55 THEN '46-55'
        WHEN age >= 56 THEN '56+'
        ELSE 'Other'
    END
ORDER BY total_revenue DESC;
